const KEY = "ziko-lang";
export const LANGS = [
  { code: "uz", label: "UZ" },
  { code: "ru", label: "RU" },
  { code: "en", label: "EN" },
];

export function getInitialLang() {
  try {
    const saved = localStorage.getItem(KEY);
    if (LANGS.some((l) => l.code === saved)) return saved;
  } catch {}
  return "uz";
}

export function saveLang(lang) {
  try {
    localStorage.setItem(KEY, lang);
  } catch {}
}

